<?php
namespace App\Http\Controllers;
use App\Models\{Comment,ContentUnlock,Like,Payment,Post,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class PostController extends Controller {
 public function create(){abort_unless(auth()->user()->canCreateContent(),403);return view('posts.create');}
 public function store(Request $r){abort_unless(auth()->user()->canCreateContent(),403);$d=$r->validate(['body'=>'nullable|string|max:5000','media'=>'nullable|file|max:102400','is_locked'=>'nullable|boolean','unlock_price'=>'nullable|required_if:is_locked,1|numeric|min:1']);$type='text';$path=null;if($r->hasFile('media')){$mime=$r->file('media')->getMimeType();$type=str_starts_with($mime,'image/')?'image':(str_starts_with($mime,'audio/')?'audio':'video');$path=$r->file('media')->store('posts','public');}$post=auth()->user()->posts()->create(['body'=>$d['body']??null,'media_type'=>$type,'media_path'=>$path,'is_locked'=>$r->boolean('is_locked'),'unlock_price'=>$r->boolean('is_locked')?$d['unlock_price']:null,'published_at'=>now()]);return redirect()->route('posts.show',$post);}
 public function show(Post $post){$post->load(['creator.creatorProfile','comments.user']);$access=!$post->is_locked || $this->hasAccess($post);return view('posts.show',compact('post','access'));}
 public function like(Post $post){$post->likes()->firstOrCreate(['user_id'=>auth()->id()]);return back();}
 public function comment(Request $r,Post $post){$d=$r->validate(['body'=>'required|string|max:1500']);$post->comments()->create(['user_id'=>auth()->id(),'body'=>$d['body']]);return back();}
 public function unlock(Request $r,Post $post){abort_if(!$post->is_locked,422);if($this->hasAccess($post))return redirect()->route('posts.show',$post);$provider=$r->validate(['provider'=>'required|in:stripe,paypal,manual'])['provider'];$payment=Payment::create(['user_id'=>auth()->id(),'creator_id'=>$post->creator_id,'type'=>'unlock','provider'=>$provider,'amount'=>$post->unlock_price,'status'=>$provider==='manual'?'pending':'completed','provider_reference'=>str()->uuid()]);if($payment->status==='completed')ContentUnlock::create(['post_id'=>$post->id,'user_id'=>auth()->id(),'payment_id'=>$payment->id,'amount'=>$post->unlock_price]);return back()->with('success',$provider==='manual'?'Manual-payment request recorded for review.':'Content unlocked.');}
 private function hasAccess(Post $post):bool {if(!auth()->check())return false;if(auth()->id()===$post->creator_id)return true;return ContentUnlock::where('post_id',$post->id)->where('user_id',auth()->id())->exists()||auth()->user()->subscriptions()->where('creator_id',$post->creator_id)->where('status','active')->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>',now()))->exists();}
}
